package com.simon.mytasks;
import android.text.*;import android.text.style.*;
import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
final class CitationUi {
 // UI-thread-only identity; weak keys do not retain an Activity after teardown.
 static final java.util.WeakHashMap<MainActivity,Object> sourceRequests=new java.util.WeakHashMap<>();
 static SpannableString render(MainActivity a,JSONObject message){
  SafeMarkdown.Document doc=CitationPolicy.document(message);SpannableString text=new SpannableString(MarkdownText.render(doc));final Store.Account owner=a.account;final long generation=a.surfaces.generation();
  for(SafeMarkdown.Style style:doc.styles)if(style.kind.startsWith("web:")){final String url=style.kind.substring(4);text.setSpan(new ClickableSpan(){@Override public void onClick(View host){if(a.alive(owner)&&a.surfaces.current(generation)&&CitationPolicy.safe(url))openWeb(a,url);}},style.start,style.end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}return text;
 }
 static void sources(MainActivity a,JSONObject message){
  final Store.Account owner=a.account;final long generation=a.surfaces.generation();JSONArray rows=CitationPolicy.sources(message);final java.util.ArrayList<JSONObject> sources=new java.util.ArrayList<>();java.util.ArrayList<String> labels=new java.util.ArrayList<>();
  for(int i=0;i<rows.length();i++){JSONObject s=rows.optJSONObject(i);if(s==null)continue;String kind=s.optString("kind");if(!kind.equals("task")&&!kind.equals("email")&&!kind.equals("saved_email")&&!(kind.equals("web")&&CitationPolicy.safe(s.optString("url"))))continue;sources.add(s);labels.add((kind.equals("web")?"Web":kind.equals("task")?"Task":"Email")+" · "+s.optString("label",s.optString("subject","Source"))+(kind.equals("web")?"\n"+s.optString("url"):""));}
  if(sources.isEmpty()){a.notice("Sources unavailable","No supported source receipts were saved for this message.");return;}
  a.dialogBuilder().setTitle("Related sources").setItems(labels.toArray(new String[0]),(dialog,which)->{if(a.alive(owner)&&a.surfaces.current(generation))panel(a,sources.get(which));}).show();
 }
 static boolean taskSource(MainActivity a,JSONObject source){if(!source.optString("kind").equals("task"))return false;String id=source.optString("task_id");if(id.isEmpty()||a.task(id)==null)a.notice("Task source unavailable","This saved task is not available in the current account. No task identity was guessed.");else a.navigate(id);return true;}
 static void openWeb(MainActivity a,String url){if(!CitationPolicy.safe(url))return;try{a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)).addCategory(Intent.CATEGORY_BROWSABLE));}catch(Exception e){a.notice("Source unavailable","No browser is available.");}}
 /** Arrow movement retains native selection. Only a short, stationary span tap is intercepted. */
 static void bindLinks(TextView body){body.setMovementMethod(new android.text.method.ArrowKeyMovementMethod(){float x,y;long down;ClickableSpan pressed;
  @Override public boolean onTouchEvent(TextView widget,Spannable buffer,MotionEvent event){
   if(event.getActionMasked()==MotionEvent.ACTION_DOWN){x=event.getX();y=event.getY();down=event.getEventTime();pressed=linkAt(widget,buffer,x,y);}
   if(event.getActionMasked()==MotionEvent.ACTION_UP){ClickableSpan target=linkAt(widget,buffer,event.getX(),event.getY());int slop=ViewConfiguration.get(widget.getContext()).getScaledTouchSlop();if(pressed!=null&&target==pressed&&event.getEventTime()-down<ViewConfiguration.getLongPressTimeout()&&Math.abs(event.getX()-x)<slop&&Math.abs(event.getY()-y)<slop&&widget.getSelectionStart()==widget.getSelectionEnd()){pressed=null;target.onClick(widget);return true;}pressed=null;}
   if(event.getActionMasked()==MotionEvent.ACTION_CANCEL)pressed=null;return super.onTouchEvent(widget,buffer,event);
  }
 });}
 static ClickableSpan linkAt(TextView widget,Spannable text,float x,float y){android.text.Layout layout=widget.getLayout();if(layout==null)return null;float px=x-widget.getTotalPaddingLeft()+widget.getScrollX();int py=(int)y-widget.getTotalPaddingTop()+widget.getScrollY();if(py<0||py>=layout.getHeight())return null;int line=layout.getLineForVertical(py);if(px<layout.getLineLeft(line)||px>layout.getLineRight(line))return null;int offset=widget.getOffsetForPosition(x,y);ClickableSpan[] spans=text.getSpans(offset,offset,ClickableSpan.class);for(ClickableSpan span:spans)if(offset>=text.getSpanStart(span)&&offset<text.getSpanEnd(span))return span;return null;}
 static void chips(MainActivity a,LinearLayout parent,JSONObject message){for(String warning:CitationPolicy.warnings(message)){TextView notice=a.label(warning,14,a.muted);notice.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);a.add(parent,notice);}}
 static void panel(MainActivity a,JSONObject s){final Object request=new Object();sourceRequests.put(a,request);final Store.Account panelOwner=a.account;final long panelGeneration=a.surfaces.generation();if(taskSource(a,s))return;if(!s.optString("kind").equals("email")&&!s.optString("kind").equals("saved_email")){String url=s.optString("url");a.dialogBuilder().setTitle(s.optString("label","Source")).setMessage(s.optString("excerpt","")+"\n"+url+"\n"+s.optString("verification","Unverified")).setNegativeButton("Close",null).setPositiveButton(CitationPolicy.safe(url)?"Open in browser":"Unavailable",(d,w)->{if(a.alive(panelOwner)&&a.surfaces.current(panelGeneration)&&CitationPolicy.safe(url))try{a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)).addCategory(Intent.CATEGORY_BROWSABLE));}catch(Exception e){a.notice("Source unavailable","No browser is available.");}}).show();return;}
  final Store.Account owner=a.account;final long generation=a.surfaces.generation();String task=s.optString("task_id"),resource=s.optString("resource_id");if(task.isEmpty()||resource.isEmpty()){a.notice("Email source unavailable","This older citation has no validated source identity. No email or URL was guessed.");return;}
  final Object root=a.root;final ConversationController controller=a.conversations;final int navigation=controller==null?0:controller.navigationVersion;final ConversationController.Listener listener=controller==null?null:controller.listener;final String thread=controller==null?"":controller.visible;
  final java.util.function.BooleanSupplier current=()->sourceRequests.get(a)==request&&a.alive(owner)&&a.surfaces.current(generation)&&a.root==root&&a.conversations==controller&&(controller==null||(controller.navigationVersion==navigation&&controller.listener==listener&&controller.visible.equals(thread)));
  Api.IO.execute(()->{try{JSONObject detail=new EmailReplyClient((m,p,b)->new Api(owner).call(m,p,b)).detail(task,resource);a.main.post(()->{if(!current.getAsBoolean())return;showDetail(a,detail);});}catch(Exception e){a.main.post(()->{if(current.getAsBoolean())a.notice("Email source unavailable","Saved email context could not be resolved. No draft was created and no update acknowledged.");});}});
 }
 static void showDetail(MainActivity a,JSONObject detail){JSONObject s=detail.optJSONObject("source");if(s==null){a.notice("Source unavailable","No validated source metadata returned.");return;}StringBuilder text=new StringBuilder();for(String k:new String[]{"account_label","sender","subject","date","excerpt","reason"})if(!s.isNull(k)&&!s.optString(k).isEmpty())text.append(s.optString(k)).append("\n\n");JSONArray thread=detail.optJSONArray("thread");if(thread!=null)for(int i=0;i<thread.length();i++){JSONObject m=thread.optJSONObject(i);if(m!=null)text.append(m.optString("sender")).append(" · ").append(m.optString("date")).append("\n").append(m.optString("subject")).append("\n").append(m.optString("body")).append("\n\n");}a.fullMessage(text.toString());}
}
